def system_lang():
    for v in ("LC_ALL", "LC_MESSAGES", "LANGUAGE", "LANG"):
        x = os.environ.get(v, "")
        if x:
            return "uk" if x.lower().startswith("uk") else "en"
    return "en"


def set_lang(choice):
    global _lang
    _lang = system_lang() if choice in (None, "auto") else (choice if choice in LANGS else "en")


def tr(key, **kw):
    s = S[key][LANGS.index(_lang)]
    return s.format(**kw) if kw else s
